{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Tocainide, which shares the 2,6-dimethylphenyl amide motif with the query, was completely bioavailable after oral administration in healthy subjects and patients, indicating this aryl amide scaffold can support high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Recainam, another 2,6-dimethylphenyl amide/urea analogue, had a mean absolute oral bioavailability of 84% in healthy subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Metolazone, a sulfamoyl/chloro-substituted diuretic structurally related to the query, is approximately 100% bioavailable in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Hydrochlorothiazide, a sulfamoyl chlorobenzene diuretic sharing the sulfonamide-chloroaryl element, has 66–75% absolute oral bioavailability, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "An isolated lidocaine subject showed F = 18%, demonstrating that the 2,6-dimethylphenyl amide can undergo first-pass loss in some cases; however, this is outweighed by higher-similarity high-F analogues and mean lidocaine bioavailability is generally above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a xipamide-like salicylanilide diuretic. The most transferable analogues sharing the 2,6-dimethylphenyl amide (tocainide, recainam) and sulfamoyl chlorobenzene diuretic elements (metolazone, hydrochlorothiazide) consistently show high oral bioavailability. The only sub-20% evidence is an isolated lidocaine subject and a glucuronide metabolite, both low-transfer or not directly relevant, so the overall evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is provided.",
    "Lidocaine shows variable first-pass metabolism, so some hepatic extraction cannot be fully excluded without query-specific data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

